-- Viewmodel-recoil comparison variant of cw_anomaly_usp. Generated by work/build_vm_recoil.py.
-- Bolt motion measured from the viewmodel: "slide" in anm_shots, 1.707 units, peak frame 1, home frame 3 at 30 fps.

AddCSLuaFile()

SWEP.Base = "cw_anomaly_usp"

SWEP.PrintName = "USP45 (VM recoil)"

SWEP.LuaViewmodelRecoil = true

SWEP.LuaViewmodelRecoilOverride = false

if CLIENT then
	SWEP.BoltBone = "slide"
	SWEP.BoltShootOffset = Vector(0, 0, 1.707)
	SWEP.BoltBonePositionRecoverySpeed = 26
	SWEP.HoldBoltWhileEmpty = true
	SWEP.DontHoldWhenReloading = true

	killicon.Add("cw_anomaly_usp_vmrecoil", "vgui/killicons/tfa_anomaly_usp", Color(255, 255, 255))
end

-- Lua recoil and the bolt bone replace the source firing animation, from the hip and in sights.
function SWEP:fireAnimFunc()
end
